-- ADR-0065 (POS S3): the store PosAPI's operations in order (a sale's receipt, a full return's
-- cancellation, a partial return's replacement) and the PosAPI's facts on the edge's state row.
-- Never a lottery or QR data. Generated by drizzle-kit.
CREATE TABLE "edge_receipts" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "edge_receipts_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"op" text NOT NULL,
	"owner_client_id" uuid NOT NULL,
	"chain_client_id" uuid NOT NULL,
	"target_client_id" uuid,
	"till_code" text NOT NULL,
	"status" text DEFAULT 'PENDING' NOT NULL,
	"receipt_type" text NOT NULL,
	"customer_tin" text,
	"customer_name" text,
	"lines" jsonb,
	"payments" jsonb,
	"total" numeric(14, 2) NOT NULL,
	"vat_total" numeric(14, 2) NOT NULL,
	"ddtd" text,
	"posapi_date" text,
	"inactive_id" text,
	"message" text,
	"attempts" integer DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp with time zone,
	"late" boolean DEFAULT false NOT NULL,
	"resolved_by_user_id" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"settled_at" timestamp with time zone,
	CONSTRAINT "edge_receipts_op" CHECK ("edge_receipts"."op" IN ('ISSUE', 'CANCEL')),
	CONSTRAINT "edge_receipts_status" CHECK ("edge_receipts"."status" IN ('PENDING', 'SENDING', 'DONE', 'ERROR', 'INDETERMINATE', 'ABANDONED')),
	CONSTRAINT "edge_receipts_type" CHECK ("edge_receipts"."receipt_type" IN ('B2C', 'B2B')),
	CONSTRAINT "edge_receipts_cancel_target" CHECK ("edge_receipts"."op" = 'ISSUE' OR "edge_receipts"."target_client_id" IS NOT NULL),
	CONSTRAINT "edge_receipts_issue_lines" CHECK ("edge_receipts"."op" = 'CANCEL' OR "edge_receipts"."lines" IS NOT NULL)
);
